\section{Experiments}
\label{sec:experiments}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth, trim=0 0 250bp 0, clip]{fig6_cn_profile}
\caption{Contamination susceptibility $\hat{c}_n$ (posterior mean $\pm$ 95\% CI), ordered by magnitude. Older models (GPT-3.5-Turbo, GPT-4-0613) show 4--6$\times$ higher susceptibility than recent models (GPT-4o).}
\label{fig:contamination_bars}
\end{figure}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth, trim=265bp 0 0 0, clip]{fig6_cn_profile}
\caption{Ability bias absorbed by MFRM-only estimation: $\Delta\theta = \hat{\theta}_{\mathrm{MFRM}} - \hat{\theta}_{\mathrm{G\text{-}MFRM}}$. The strong correlation with $\hat{c}_n$ (Spearman $\rho = 1.0$) confirms that contamination inflates MFRM ability estimates for high-$c_n$ models, as predicted by the OVB analysis (Section~\ref{sec:confounding}).}
\label{fig:bias_absorption}
\end{figure}

\subsection{Setup}
\label{sec:setup}

\paragraph{Data and models.} We evaluate on Arena-Hard \citep{li2024arenahard}, a benchmark of 316 multi-turn conversational items selected for high separability among frontier models. After filtering for coverage, the evaluation set comprises 176 items in a connected incomplete design (36{,}231 observations; 66.0\% fill rate of the full $N \times I \times J$ tensor). Seventeen target models spanning proprietary and open-source families are evaluated: the original 8 models (GPT-4o, GPT-4o-mini, Qwen2.5-72B, LLaMA-3.3-70B, Qwen3-8B, Gemma-2-9B, GPT-4-0613, GPT-3.5-Turbo) plus 9 additional models (Claude-3.5-Sonnet, GPT-4-Turbo, LLaMA-3.1-70B, Gemma-2-27B, Claude-3-Opus, LLaMA-3-70B, Mixtral-8x22B, Claude-3-Haiku, LLaMA-3-8B). Ground-truth rankings are derived from Chatbot Arena human preference data \citep{zheng2023mtbench}.

\paragraph{Judges.} Nine LLM judges score responses in position-swapped pairwise mode: GPT-5.5, Claude Opus 4.7, Claude Sonnet 4.6, DeepSeek-V4-Pro, Gemini-2.5-Pro, Mistral-Large-2, LLaMA-3.3-70B, Qwen2.5-72B, and Qwen3-235B. Seven cover all 17 targets; two cover only the original 8, yielding an asymmetric connected design. Two models serve as both judge and target; $d_j$ absorbs self-evaluation bias ($\tau$ unchanged when excluding self-judging; Appendix~\ref{app:self_eval}).

\paragraph{Exposure estimation.} Per-item $e_i$ follows the two-source pipeline in \S\ref{sec:staged} (75\% reference anchoring, 25\% cross-model agreement; robust to weight configuration, $\rho \geq 0.998$; Appendix~\ref{app:weight_robustness}).

\paragraph{MCMC.} NumPyro NUTS, 4{,}000 warmup $+$ 4{,}000 samples $\times$ 4 chains (target acceptance 0.95). Convergence: $\hat{R} < 1.05$, ESS $> 100$ \citep{vehtari2021rhat, gelman2013bda}.

\subsection{Main Results}
\label{sec:main_results}

We compare G-MFRM against seven baselines that address judge bias or contamination separately (Table~\ref{tab:main_results}): Raw Average, MFRM-only (Eq.~\ref{eq:mfrm}), Sequential (MFRM then contamination adjustment), CyclicJudge \citep{cyclicjudge2026}, CyclicJudge+discard, DCR Factor \citep{dcr2025}, and Preference Leakage calibration \citep{preference_leakage2026}. All methods are evaluated by Kendall $\tau$ and Spearman $\rho$ against Chatbot Arena human rankings.

\paragraph{Synthetic validation.} On synthetic data ($N = 50$, 20 seeds), G-MFRM reduces ability RMSE by 44\% relative to sequential estimation ($p < 10^{-6}$) and improves ranking accuracy ($\tau$: $0.922$ vs.\ $0.859$, Wilcoxon $p < 0.001$). Contamination susceptibility is recovered with Pearson $r = 0.81$.

\paragraph{Predictive fit.} On Arena-Hard, LOO cross-validation strongly favors G-MFRM over MFRM-only ($\Delta\mathrm{ELPD}_{\mathrm{LOO}} = -55.7$, SE $= 9.4$, $|\Delta/\mathrm{SE}| = 5.9$; \citealp{vehtari2017loo}), with stacking weight 1.0 and all Pareto $\hat{k} < 0.7$ (Appendix~\ref{app:loo_comparison}).

\paragraph{Exposure coverage and ranking accuracy.} Despite improved predictive fit, G-MFRM's ranking accuracy on real data depends on exposure estimation quality. At $N = 17$, the full item set (500 items) has only 46\% of items with non-zero exposure estimates; G-MFRM over-corrects on the remaining items, yielding $\Delta\tau = -0.044$ relative to the raw average ($\tau = 0.794$ vs.\ $0.838$). We trace this degradation through three item subsets with increasing exposure coverage:
%
\begin{itemize}
    \item Full set (500 items, 46\% $e_i > 0$): $\Delta\tau = -0.044$
    \item Filtered set (317 items, 73\% $e_i > 0$): $\Delta\tau = -0.015$
    \item Exposed-only (231 items, 100\% $e_i > 0$): $\Delta\tau = 0.000$
\end{itemize}
%
The monotonic decrease ($-0.044 \to -0.015 \to 0.000$) establishes that over-correction is entirely attributable to incomplete exposure coverage. Two control variants confirm the mechanism: MFRM-only on the filtered set yields $\Delta\tau = 0.000$, isolating the degradation to the contamination gating term; a contamination-only variant without severity modeling yields $\Delta\tau = -0.118$, demonstrating that naive linear contamination deduction without joint calibration is catastrophically harmful.

\paragraph{Contamination diagnostics.} G-MFRM's primary real-data contribution is calibrated per-model contamination estimation. The contamination susceptibility profile (Figure~\ref{fig:contamination_bars}) reveals a clear gradient by model age: older models show $\hat{c}_n > 4$ (GPT-3.5-Turbo: $5.60$; GPT-4-0613: $4.20$), while recent models show near-zero susceptibility (GPT-4o: $0.88$; GPT-4o-mini: $0.93$). MFRM-only estimation absorbs this contamination signal into ability estimates, inflating $\hat{\theta}$ for the most contaminated models by up to 0.79 logits (Figure~\ref{fig:bias_absorption}; Spearman $\rho = 1.0$ between $\hat{c}_n$ and $\Delta\theta$). All parameters achieve $\hat{R} \leq 1.03$ with ESS $\geq 174$ (Appendices~\ref{app:item_diagnostics} and~\ref{app:ppc}).

\paragraph{Judge severity and panel design.} Judge severity profiles span 1.34 logits, with proprietary judges scoring more strictly (Figure~\ref{fig:judge_severity}). Contamination--ability separation improves with severity diversity: panels with $k \geq 4$ judges covering the severity extremes provide the most reliable diagnostic output (Appendix~\ref{app:judge_count}).

\subsection{Error Propagation and Ablation}
\label{sec:error_prop_results}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{fig_ablation_rmse}
\caption{Ablation on synthetic data ($N = 50$, 20 seeds). Joint estimation drives the improvement: staged estimation doubles $\theta$-RMSE ($p < 0.001$). Continuous gating provides a moderate gain over binary ($p < 0.001$); removing judge severity $d_j$ has negligible effect on ability recovery (n.s.).}
\label{fig:ablation}
\end{figure}

Table~\ref{tab:error_prop} validates the theoretical prediction (\S\ref{sec:error_prop}): below $\sigma = 0.2$, ability RMSE increases by 5.9\% and contamination RMSE by 7.9\%; beyond the threshold ($\sigma = 0.5$), degradation becomes substantial. Ablation (Figure~\ref{fig:ablation}; full results in Table~\ref{tab:ablation}, Appendix~\ref{app:ablation}) confirms joint estimation as the dominant contributor ($2.0\times$ $\theta$-RMSE increase under staged estimation, $p < 0.001$) and continuous gating over binary ($c_n$-RMSE $-$40\%, $p < 0.001$).

